{"code": "import re
from decimal import Decimal, ROUND_HALF_EVEN

_MONEY_RE = re.compile(r"^-?\d+(\.\d+)?$")

_TWO_PLACES = Decimal("0.01")
_ZERO = Decimal("0.00")
_HUNDRED = Decimal("100")


def _parse_decimal(raw: object, label: str) -> Decimal:
    if not isinstance(raw, str) or not _MONEY_RE.match(raw):
        raise ValueError(f"{label} is malformed: {raw!r}")
    return Decimal(raw)


def _round(value: Decimal) -> Decimal:
    result = value.quantize(_TWO_PLACES, rounding=ROUND_HALF_EVEN)
    if result == 0:
        result = _ZERO
    return result


def apply_discounts(subtotal: str, discounts: list[dict]) -> str:
    """Apply a list of stacking percent/amount discounts to a subtotal.

    Each discount is applied in order to the running total left by the
    previous one (compounding, not additive), rounded to two decimal
    places after every step, and clamped at zero. Returns the final
    total as a decimal string with exactly two decimal places.
    """
    subtotal_amount = _parse_decimal(subtotal, "subtotal")
    if subtotal_amount < 0:
        raise ValueError(f"subtotal is negative: {subtotal!r}")

    running_total = _round(subtotal_amount)

    for entry in discounts:
        if not isinstance(entry, dict):
            raise ValueError(f"discount entry is not a mapping: {entry!r}")
        if "kind" not in entry or "value" not in entry:
            raise ValueError(f"discount entry missing kind/value: {entry!r}")

        kind = entry["kind"]
        if kind not in ("percent", "amount"):
            raise ValueError(f"discount kind is invalid: {kind!r}")

        value = _parse_decimal(entry["value"], "discount value")
        if value < 0:
            raise ValueError(f"discount value is negative: {entry['value']!r}")
        if kind == "percent" and value > 100:
            raise ValueError(f"percent discount value exceeds 100: {entry['value']!r}")

        if kind == "percent":
            running_total = running_total * (_HUNDRED - value) / _HUNDRED
        else:
            running_total = running_total - value

        running_total = _round(running_total)
        if running_total < 0:
            running_total = _ZERO

    return f"{running_total:.2f}"
